17	// Parameter names accepted on every entry point. The first name of each list
18	// is the canonical name used in responses.
19	var (
20		serviceNameKeys = []string{"service_name", "serviceName", "service"}
21		instanceIDKeys  = []string{"instance_id", "instanceId", "instance", "id"}
22		addressKeys     = []string{"address", "addr", "host", "endpoint"}
23		portKeys        = []string{"port"}
24		healthKeys      = []string{"health", "healthy", "status", "state"}
25		weightKeys      = []string{"weight"}
26		heartbeatKeys   = []string{"heartbeat_at", "heartbeatAt", "heartbeat", "heartbeat_time", "heartbeatTime", "last_heartbeat"}
27		evaluateAtKeys  = []string{"evaluate_at", "evaluateAt", "at", "now", "evaluate_time", "evaluateTime"}
28		timeoutKeys     = []string{"heartbeat_timeout", "heartbeatTimeout", "timeout", "timeout_seconds", "timeoutSeconds", "heartbeat_timeout_seconds"}
29	)
30	
31	type apiError struct {
32		status  int
33		code    string
34		message string
35	}
36	
37	func errInvalidParameter(message string) *apiError {
38		return &apiError{http.StatusBadRequest, "invalid_parameter", message}
39	}
40	
41	func errInstanceNotFound() *apiError {
42		return &apiError{http.StatusNotFound, "instance_not_found", "service instance not found"}
43	}
44	
45	func errStorageUnavailable() *apiError {
46		return &apiError{http.StatusServiceUnavailable, "storage_unavailable", "database is not available"}
47	}
48	
49	func writeError(c *gin.Context, e *apiError) {
50		c.JSON(e.status, gin.H{"error": gin.H{"code": e.code, "message": e.message}})
51	}
52	
53	// trimJSONWhitespace removes only the JSON whitespace characters U+0020
54	// space, U+0009 tab, U+000A line feed and U+000D carriage return from both
55	// ends. bytes.TrimSpace must not be used here: it trims every Unicode
56	// whitespace, so a body of NBSP (U+00A0), em space (U+2003), ideographic
57	// space (U+3000), U+000B or U+000C would be mistaken for an empty body and
58	// silently fall back to query parameters even though JSON parsers reject
59	// those bytes outside a string. Whitespace that is legal only inside JSON
60	// strings is untouched there, since this scans only the document framing.
61	func trimJSONWhitespace(raw []byte) []byte {
62		start, end := 0, len(raw)
63		for start < end && isJSONWhitespace(raw[start]) {
64			start++
65		}
66		for end > start && isJSONWhitespace(raw[end-1]) {
67			end--
68		}
69		return raw[start:end]
70	}
71	
72	func isJSONWhitespace(b byte) bool {
73		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
74	}
75	
76	// paramBag merges JSON body fields and query parameters, keeping route path
77	// parameters separate. Body fields win over query parameters; path
78	// parameters are read through locateText and win over both of them.
79	type paramBag struct {
80		values map[string]any
81		path   map[string]any
82	}
83	
84	func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
85		bag := &paramBag{
86			values: make(map[string]any),
87			path:   make(map[string]any),
88		}
89	
90		for key, values := range c.Request.URL.Query() {
91			if len(values) > 0 {
92				bag.values[key] = values[0]
93			}
94		}
95	
96		// A non-empty body must be exactly one JSON object surrounded only by
97		// JSON whitespace: a null, array or other bare value, a truncated object,
98		// a second JSON value or a stray closing bracket are all parameter
99		// errors, even when the query parameters alone would complete the
100		// request. An empty body, or one made only of the four JSON whitespace
101		// bytes (space, tab, line feed, carriage return), carries no fields, so
102		// the query-parameter lookup rules still apply; other Unicode whitespace
103		// such as NBSP is not JSON whitespace and is rejected. An empty {}
104		// object merges with query parameters like any other (empty) field set.
105		if c.Request.Body != nil {
106			body, present, apiErr := readOptionalObjectBody(c)
107			if apiErr != nil {
108				return nil, apiErr
109			}
110			if present {
111				for key, value := range body {
112					bag.values[key] = value
113				}
114			}
115		}
116	
117		for _, param := range c.Params {
118			bag.path[param.Key] = param.Value
119		}
120		return bag, nil
121	}
122	
123	// decodeSingleJSONObject decodes raw as exactly one complete JSON object
124	// surrounded only by JSON whitespace. It returns present=false for an empty
125	// payload or one containing only JSON whitespace bytes; payloads of other
126	// Unicode whitespace are not empty and fall through to the decoder, which
127	// rejects them. A JSON null, array or other bare value, a truncated object,
128	// a second JSON value, or a stray closing bracket after the object
129	// (immediately or across whitespace) are all parameter errors.
130	//
131	// Decoder.More cannot be used to check completeness: it reports false for a
132	// dangling "}" or "]" because those are not value tokens. A second Decode
133	// must therefore return exactly io.EOF, which is true only once the object
134	// has ended and nothing but whitespace remains.
135	func decodeSingleJSONObject(raw []byte) (body map[string]any, present bool, apiErr *apiError) {
136		if len(trimJSONWhitespace(raw)) == 0 {
137			return nil, false, nil
138		}
139		decoder := json.NewDecoder(bytes.NewReader(raw))
140		// UseNumber keeps every JSON number as its literal text so integer
141		// fields (port) can be parsed exactly, without the float64 rounding
142		// that json.Unmarshal would apply.
143		decoder.UseNumber()
144		var decoded map[string]any
145		if err := decoder.Decode(&decoded); err != nil || decoded == nil {
146			return nil, false, errInvalidParameter("request body must be a JSON object")
147		}
148		var trailing json.RawMessage
149		if err := decoder.Decode(&trailing); err != io.EOF {
150			return nil, false, errInvalidParameter("request body must be a single JSON object")
151		}
152		return decoded, true, nil
153	}
154	
155	// readOptionalObjectBody reads a body that may be absent: no body or only
156	// the four JSON whitespace bytes yields present=false so the entry falls
157	// back to its query parameter rules, while every other non-empty payload
158	// (including other Unicode whitespace such as NBSP) is a parameter error.
159	func readOptionalObjectBody(c *gin.Context) (map[string]any, bool, *apiError) {
160		if c.Request.Body == nil {
161			return nil, false, nil
162		}
163		raw, err := io.ReadAll(c.Request.Body)
164		if err != nil {
165			return nil, false, errInvalidParameter("request body cannot be read")
166		}
167		return decodeSingleJSONObject(raw)
168	}
169	
170	// readStrictObjectBody requires the body to be exactly one JSON object
171	// surrounded only by JSON whitespace. It is used by the batch entries whose
172	// contract forbids query-parameter merging: a missing/empty body, a JSON
173	// null, array or other bare value, a second JSON value, or a stray closing
174	// bracket after the object are all parameter errors, even when the first
175	// object carries complete, valid entries.
176	func readStrictObjectBody(c *gin.Context) (map[string]any, *apiError) {
177		if c.Request.Body == nil {
178			return nil, errInvalidParameter("request body must be a JSON object")
179		}
180		raw, err := io.ReadAll(c.Request.Body)
181		if err != nil {
182			return nil, errInvalidParameter("request body cannot be read")
183		}
184		body, present, apiErr := decodeSingleJSONObject(raw)
185		if apiErr != nil {
186			return nil, apiErr
187		}
188		if !present {
189			return nil, errInvalidParameter("request body must be a JSON object")
190		}
191		return body, nil
192	}
193	
194	// buildStrictObjectBag is a paramBag populated from exactly one JSON object:
195	// unlike buildParamBag it never reads query parameters, so a rejected or
196	// missing body field cannot be repaired through the URL. Path parameters are
197	// still recorded so path locators keep winning.
198	func buildStrictObjectBag(c *gin.Context) (*paramBag, *apiError) {
199		body, apiErr := readStrictObjectBody(c)
200		if apiErr != nil {
201			return nil, apiErr
202		}
203		bag := &paramBag{
204			values: make(map[string]any, len(body)),
205			path:   make(map[string]any),
206		}
207		for key, value := range body {
208			bag.values[key] = value
209		}
210		for _, param := range c.Params {
211			bag.path[param.Key] = param.Value
212		}
213		return bag, nil
214	}
215	
216	func (b *paramBag) get(keys []string) (any, bool) {
217		for _, key := range keys {
218			if value, ok := b.values[key]; ok {
219				return value, true
220			}
221		}
222		return nil, false
223	}
224	
225	// locateText resolves one locator field (service name or instance id). A
226	// value carried by the route path always wins: a conflicting, empty or
227	// non-string value of the same field in the body or query string is ignored,
228	// and a blank path segment is a parameter error that cannot be filled from
229	// another source. Only when the route carries no such segment does the field
230	// fall back to the existing body/query lookup rules.
231	func (b *paramBag) locateText(pathKey string, keys []string, message string) (string, *apiError) {
232		if raw, fromPath := b.path[pathKey]; fromPath {
233			text := strings.TrimSpace(stringValue(raw))
234			if text == "" {
235				return "", errInvalidParameter(message)
236			}
237			return text, nil
238		}
239		return b.requiredText(keys, message)
240	}
241	
242	// readJSONObject requires the request body to be a single JSON object. An
243	// empty body, a body of only JSON whitespace bytes, a JSON array or any
244	// non-object payload is a parameter error; other Unicode whitespace such as
245	// NBSP is likewise rejected by the parser. It is used by the batch entry
246	// points whose contract forbids merging query parameters or accepting a bare
247	// value.
248	func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
249		if c.Request.Body == nil {
250			return nil, errInvalidParameter("request body must be a JSON object")
251		}
252		raw, err := io.ReadAll(c.Request.Body)
253		if err != nil {
254			return nil, errInvalidParameter("request body cannot be read")
255		}
256		if len(trimJSONWhitespace(raw)) == 0 {
257			return nil, errInvalidParameter("request body must be a JSON object")
258		}
259		var body map[string]any
260		if err := json.Unmarshal(raw, &body); err != nil || body == nil {
261			return nil, errInvalidParameter("request body must be a JSON object")
262		}
263		return body, nil
264	}
265	
266	func stringValue(value any) string {
267		if text, ok := value.(string); ok {
268			return text
269		}
270		return ""
271	}
272	
273	// readHealthyInput accepts a new healthy state for one instance from either a
274	// JSON body field ("healthy": true|false) or the ?healthy=true|false query
275	// parameter. The JSON field wins when both carry it. JSON accepts only
276	// booleans, while the query parameter accepts only the lowercase text "true"
277	// or "false"; every other representation is a parameter error. As on every
278	// other entry, only an absent body or one made solely of the four JSON
279	// whitespace bytes falls back to the query parameter; other Unicode
280	// whitespace makes the body a parameter error.
281	func readHealthyInput(c *gin.Context) (bool, *apiError) {
282		queryValue, queryPresent := c.GetQuery("healthy")
283	
284		if c.Request.Body != nil {
285			raw, err := io.ReadAll(c.Request.Body)
286			if err != nil {
287				return false, errInvalidParameter("request body cannot be read")
288			}
289			if len(trimJSONWhitespace(raw)) > 0 {
290				var body map[string]any
291				if err := json.Unmarshal(raw, &body); err != nil || body == nil {
292					return false, errInvalidParameter("request body must be a JSON object")
293				}
294				if value, present := body["healthy"]; present {
295					healthy, ok := strictBoolValue(value)
296					if !ok {
297						return false, errInvalidParameter("healthy must be a boolean true or false")
298					}
299					return healthy, nil
300				}
301			}
302		}
303	
304		if !queryPresent {
305			return false, errInvalidParameter("healthy must be a boolean true or false")
306		}
307		switch queryValue {
308		case "true":
309			return true, nil
310		case "false":
311			return false, nil
312		default:
313			return false, errInvalidParameter("healthy must be a boolean true or false")
314		}
315	}
316	
317	// requiredText returns the trimmed text for the first matching key, or an error
318	// when the value is missing or blank.
319	func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
320		value, ok := b.get(keys)
321		if !ok {
322			return "", errInvalidParameter(message)
323		}
324		text := strings.TrimSpace(stringValue(value))
325		if text == "" {
326			return "", errInvalidParameter(message)
327		}
328		return text, nil
329	}
330	
331	// positiveNumber accepts weights: only numbers strictly greater than zero.
332	func positiveNumber(value any) (float64, bool) {
333		number, ok := toFloat(value)
334		if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
335			return 0, false
336		}
337		return number, true
338	}
339	
340	// parsePortValue accepts a non-negative integer port number in the range
341	// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
342	// their decimal text with exact integer semantics: values above 2^53 keep
343	// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
344	// their integer value, and the int64 bound is enforced without rounding, so
345	// 9223372036854775808 is rejected instead of overflowing the conversion.
346	func parsePortValue(value any) (int64, bool) {
347		switch typed := value.(type) {
348		case json.Number:
349			return parsePortText(typed.String())
350		case string:
351			return parsePortText(strings.TrimSpace(typed))
352		case float64:
353			// A float64 at or beyond 2^63 cannot be a valid port: the largest
354			// exactly representable candidate below it is 2^63-1024, and the
355			// int64 conversion of anything larger would overflow.
356			if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
357				typed < 0 || typed >= 9223372036854775808.0 {
358				return 0, false
359			}
360			return int64(typed), true
361		case int:
362			return int64(typed), typed >= 0
363		case int64:
364			return typed, typed >= 0
365		default:
366			return 0, false
367		}
368	}
369	
370	// portNumberPattern is the decimal grammar a port may use: an integer or a
371	// fixed/scientific decimal with an optional sign.
372	var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)
373	
374	// parsePortText parses the exact integer value of a decimal number without
375	// going through float64. The mantissa is kept as a digit string and the
376	// exponent as a small int, so huge exponents are rejected by digit counting
377	// instead of materializing enormous integers.
378	func parsePortText(text string) (int64, bool) {
379		// Fast path: a plain decimal integer, exact for the whole int64 range.
380		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
381			return number, number >= 0
382		}
383		if !portNumberPattern.MatchString(text) {
384			return 0, false
385		}
386		negative := strings.HasPrefix(text, "-")
387		mantissa := strings.TrimLeft(text, "+-")
388		exponent := 0
389		if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
390			expText := mantissa[at+1:]
391			mantissa = mantissa[:at]
392			if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
393				// |exponent| >= 10^6: the value is either far beyond the int64
394				// bound or far below one; only an all-zero mantissa is still
395				// exactly zero.
396				if allZeroDigits(mantissa) {
397					return 0, true
398				}
399				return 0, false
400			}
401			exponent, _ = strconv.Atoi(expText)
402		}
403		intPart, fracPart := mantissa, ""
404		if at := strings.IndexByte(mantissa, '.'); at >= 0 {
405			intPart, fracPart = mantissa[:at], mantissa[at+1:]
406		}
407		// value = digits * 10^k
408		digits := intPart + fracPart
409		k := exponent - len(fracPart)
410		digits = strings.TrimLeft(digits, "0")
411		for strings.HasSuffix(digits, "0") {
412			digits = digits[:len(digits)-1]
413			k++
414		}
415		if digits == "" {
416			return 0, true // exact zero, in any form
417		}
418		if negative || k < 0 {
419			// A negative port is out of range; a negative remaining exponent
420			// leaves a fractional part, so the value is not an integer.
421			return 0, false
422		}
423		if len(digits)+k > 19 {
424			return 0, false
425		}
426		number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
427		if err != nil {
428			return 0, false // 19 digits but beyond math.MaxInt64
429		}
430		return number, true
431	}
432	
433	// allZeroDigits reports whether a mantissa (digits with an optional dot)
434	// denotes zero.
435	func allZeroDigits(mantissa string) bool {
436		for _, r := range mantissa {
437			if r != '0' && r != '.' {
438				return false
439			}
440		}
441		return true
442	}
443	
444	// strictBoolValue accepts only JSON boolean true or false. Every other
445	// representation (text, numbers) is rejected so all implementations agree.
446	func strictBoolValue(value any) (bool, bool) {
447		typed, ok := value.(bool)
448		return typed, ok
449	}
450	
451	func toFloat(value any) (float64, bool) {
452		switch typed := value.(type) {
453		case float64:
454			return typed, true
455		case int:
456			return float64(typed), true
457		case int64:
458			return float64(typed), true
459		case json.Number:
460			number, err := typed.Float64()
461			if err != nil {
462				return 0, false
463			}
464			return number, true
465		case string:
466			number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
467			if err != nil {
468				return 0, false
469			}
470			return number, true
471		default:
472			return 0, false
473		}
474	}
475	
476	func parseHealthValue(value any) (bool, bool) {
477		switch typed := value.(type) {
478		case bool:
479			return typed, true
480		case float64:
481			switch typed {
482			case 1:
483				return true, true
484			case 0:
485				return false, true
486			}
487		case json.Number:
488			if number, err := typed.Float64(); err == nil {
489				switch number {
490				case 1:
491					return true, true
492				case 0:
493					return false, true
494				}
495			}
496		case string:
497			switch strings.ToLower(strings.TrimSpace(typed)) {
498			case "healthy", "up", "on", "true", "1", "yes":
499				return true, true
500			case "unhealthy", "down", "off", "false", "0", "no":
501				return false, true
502			}
503		}
504		return false, false
505	}
506	
507	// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
508	// once converted to UTC: the lower bound is included, the upper bound is
509	// excluded. These are exactly the instants the RFC3339 storage format can
510	// write and read back, so anything outside could never round-trip.
511	var (
512		minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
513		maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
514	)
515	
516	func inAcceptedTimeRange(t time.Time) bool {
517		t = t.UTC()
518		return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
519	}
520	
521	func parseTimeValue(value any) (time.Time, bool) {
522		switch typed := value.(type) {
523		case string:
524			text := strings.TrimSpace(typed)
525			if text == "" {
526				return time.Time{}, false
527			}
528			if number, err := strconv.ParseFloat(text, 64); err == nil {
529				return unixTimeInRange(number)
530			}
531			for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
532				if parsed, err := time.Parse(layout, text); err == nil {
533					if !inAcceptedTimeRange(parsed) {
534						return time.Time{}, false
535					}
536					return parsed, true
537				}
538			}
539		case float64:
540			return unixTimeInRange(typed)
541		case json.Number:
542			number, err := typed.Float64()
543			if err != nil {
544				return time.Time{}, false
545			}
546			return unixTimeInRange(number)
547		}
548		return time.Time{}, false
549	}
550	
551	// unixTimeInRange converts a Unix second count that lands inside the
552	// accepted range. The range check runs on the float itself, before any int64
553	// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
554	// out-of-range finite values are rejected instead of overflowing and
555	// wrapping back into a valid-looking date.
556	func unixTimeInRange(seconds float64) (time.Time, bool) {
557		if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
558			seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
559			return time.Time{}, false
560		}
561		return unixTime(seconds), true
562	}
563	
564	func unixTime(seconds float64) time.Time {
565		whole := int64(seconds)
566		fraction := seconds - float64(whole)
567		return time.Unix(whole, int64(fraction*1e9)).UTC()
568	}
569	
570	// parseTimeout accepts a number of seconds or a duration string such as "30s".
571	// A non-positive duration is reported as invalid by the caller.
572	func parseTimeout(value any) (time.Duration, bool) {
573		switch typed := value.(type) {
574		case float64:
575			if math.IsNaN(typed) || math.IsInf(typed, 0) {
576				return 0, false
577			}
578			return time.Duration(typed * float64(time.Second)), true
579		case json.Number:
580			number, err := typed.Float64()
581			if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
582				return 0, false
583			}
584			return time.Duration(number * float64(time.Second)), true
585		case string:
586			text := strings.TrimSpace(typed)
587			if text == "" {
588				return 0, false
589			}
590			if duration, err := time.ParseDuration(text); err == nil {
591				return duration, true
592			}
593			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
594				return time.Duration(number * float64(time.Second)), true
595			}
596		}
597		return 0, false
598	}
